const body = $json.body || {};
const project = (body.project || 'atlas').toLowerCase().trim();

const mapping = {
  'atlas': { path: 'Projects/Atlas/logs', title: 'Atlas (AI-OS & Automation Engine)' },
  'courses': { path: 'Courses', title: 'Образование и курсы (Courses)' },
  'dacha': { path: 'Projects/Dacha/logs', title: 'Проект Дача' },
  'nastya': { path: 'Projects/Nastya/logs', title: 'Проект Настя' },
  'dzen': { path: 'Projects/Dzen/logs', title: 'Яндекс Дзен' },
  'other': { path: 'Projects/Other/logs', title: 'Другие проекты (Other)' }
};

const target = mapping[project] || mapping['atlas'];
return [{
  json: {
    projectKey: project,
    projectTitle: target.title,
    repoPath: target.path
  }
}];

const resp = $json;
const projectInfo = $('Resolve Project Path').first().json;
const statePath = projectInfo.repoPath === 'Courses' ? 'Courses/project_state.md' : projectInfo.repoPath.replace(/\/logs$/, '') + '/project_state.md';

let files = [];
if (resp.statusCode === 200 && Array.isArray(resp.body)) {
  files = resp.body.filter(f => 
    f.type === 'file' && 
    f.name.endsWith('.md') && 
    !f.name.endsWith('-raw.md') &&
    !f.name.startsWith('.')
  );
}

if (files.length === 0) {
  // Graceful fallback to project_state.md
  return [{
    json: {
      found: true,
      isFallbackState: true,
      latestFile: {
        name: 'project_state.md',
        path: statePath,
        sha: 'state-sha',
        size: 0
      },
      projectInfo: projectInfo
    }
  }];
}

files.sort((a, b) => b.name.localeCompare(a.name));
const latest = files[0];

return [{
  json: {
    found: true,
    isFallbackState: false,
    latestFile: {
      name: latest.name,
      path: latest.path,
      sha: latest.sha,
      size: latest.size
    },
    projectInfo: projectInfo
  }
}];

const fetchResp = $json;
const pickData = $('Pick Latest Conspect').first().json;

if (!pickData.found) {
  return [{
    json: {
      statusCode: 404,
      response: {
        status: 'error',
        message: pickData.error || 'Логи не найдены'
      }
    }
  }];
}

let content = '';
const b = fetchResp.body || fetchResp;

if (b && typeof b.content === 'string') {
  try {
    content = Buffer.from(b.content, 'base64').toString('utf-8');
  } catch(e) {
    content = b.content;
  }
} else if (typeof b === 'string') {
  content = b;
} else if (b && typeof b === 'object') {
  content = JSON.stringify(b, null, 2);
}

const projectInfo = pickData.projectInfo;
const filename = pickData.latestFile.name;

let formattedDate = 'не указана';
const tsMatch = filename.match(/^(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})/);
if (tsMatch) {
  formattedDate = tsMatch[1] + '-' + tsMatch[2] + '-' + tsMatch[3] + ' ' + tsMatch[4] + ':' + tsMatch[5] + ':' + tsMatch[6];
}

const prompt = 'Вы продолжаете работу над проектом: **' + projectInfo.projectTitle + '** (ID: `' + projectInfo.projectKey + '`).\n\n' +
  'Ниже приведён актуальный срез общей памяти (Second Brain), зафиксированный предыдущей AI-моделью.\n' +
  'Файл памяти: `' + pickData.latestFile.path + '`\n' +
  'Дата фиксации: ' + formattedDate + '\n\n' +
  '==================== [АКТУАЛЬНАЯ ПАМЯТЬ ПРОЕКТА] ====================\n\n' +
  content + '\n\n' +
  '====================================================================\n\n' +
  '⚡ ДИРЕКТИВА АВТОНОМНОГО ИСПОЛНЕНИЯ ДЛЯ МОДЕЛИ:\n' +
  '1. Твоя задача — СРАЗУ, В ПЕРВОМ ЖЕ ОТВЕТЕ, приступить к выполнению задачи из блока «Следующий конкретный шаг (Next Step)».\n' +
  '2. СТРОЖАЙШЕ ЗАПРЕЩЕНО:\n' +
  '   - Спрашивать пользователя «Чем я могу помочь?», «Что делать дальше?» или просить подтвердить продолжение работы.\n' +
  '   - Переспрашивать то, что уже решено и зафиксировано в контексте выше.\n' +
  '   - Заниматься простым пересказом входного контекста.\n' +
  '3. Сразу выдавай готовый результат выполнения шага: код, план, архитектуру, решение или текст.\n' +
  '4. В самом конце своего ответа сформируй краткий блок отчёта по формату AI-OS Report:\n' +
  '   - Что фактически сделано\n' +
  '   - Принятые решения\n' +
  '   - Следующий конкретный шаг для следующей модели\n' +
  '   (это позволит пользователю сохранить твой отчёт обратно в Second Brain в 1 клик).';

return [{
  json: {
    statusCode: 200,
    response: {
      status: 'ok',
      project: projectInfo.projectKey,
      projectTitle: projectInfo.projectTitle,
      filename: filename,
      filePath: pickData.latestFile.path,
      updatedAt: formattedDate,
      contentLength: content.length,
      prompt: prompt
    }
  }
}];
